TOPIC = 'Secondary hypertension'
rows = []


def S(h, t, *children):
    return h, [(t, list(children))]


def add(*args, **kwargs):
    rows.append(Q(*args, **kwargs))


add(TOPIC, 'Primary Aldosteronism: Broader Screening in 2025',
 'Which statement best represents the Endocrine Society 2025 PA screening recommendation, including for adults with controlled hypertension and normal potassium?',
 'Consider aldosterone and renin screening in all hypertensive adults, with resource-dependent implementation', [
 ('Reserve screening for hypertension accompanied by spontaneous hypokalemia', 'Hypokalemia identifies a particularly important phenotype, but many patients with primary aldosteronism are normokalemic. Restricting testing to this feature would miss cases and is narrower than the current conditional recommendation.'),
 ('Reserve screening for failure of three optimally dosed antihypertensives', 'Resistant hypertension remains a high-priority reason to test. It is not a prerequisite under the broader 2025 recommendation, so good control on one drug does not automatically exclude screening.'),
 ('Screen with adrenal CT when potassium is normal and biochemical tests are less informative', 'CT is useful for adrenal anatomy after appropriate endocrine assessment, especially when surgery is considered. Normal potassium does not make aldosterone and renin uninformative, and an adrenal nodule does not establish functional aldosterone excess.')],
 [S('Screening Recommendation', '**The Endocrine Society 2025 guidance conditionally suggests PA screening across the hypertensive population.** Feasibility, resources and local expertise affect implementation; this should not be presented as an unconditional mandate for every setting.',
    'Normal potassium does not exclude PA. Renal potassium wasting depends on the degree of mineralocorticoid action and other factors, so overt hypokalemia represents only part of the disease spectrum.',
    'When testing capacity is limited, resistant hypertension, spontaneous or diuretic-associated hypokalemia and other strong clinical clues remain important priorities. An apparently mild BP phenotype can still conceal a specifically treatable cause.'),
  S('Initial Evaluation', '**Measure aldosterone and renin, and interpret their relationship in the clinical and assay context.** Check potassium because hypokalemia can suppress aldosterone and create a misleadingly reassuring result.',
    'Obtain samples under standardized conditions, generally in the morning with the patient seated, without recent dietary sodium restriction. Review medicines that alter renin or aldosterone and plan changes only when clinically safe.',
    'An elevated ratio is a screening clue, not a diagnosis based on arithmetic alone: very low renin can generate a high ratio even when aldosterone is not convincingly elevated. Conversely, a negative test during hypokalemia may need repetition after correction. A positive biochemical assessment leads to an individualized pathway for suppression testing, targeted medical treatment or surgical evaluation. CT cannot replace this physiological assessment because incidental nodules are common and bilateral functional disease may have unremarkable anatomy. Detecting PA matters because treatment can address aldosterone-mediated risk as well as the pressure number.')], ['PA2025', 'AHA2025'],style='direct')

add(TOPIC, 'Aldosterone–Renin Ratio: Potassium and Medication Effects',
 'During PA screening, an adult taking metoprolol has potassium 3.0 mmol/L, immunoassay aldosterone 8 ng/dL and PRA 0.1 ng/mL/h. The ARR is 80. What is the best interpretation?',
 'The result is confounded; correct potassium and repeat with a safe medication strategy', [
 ('The ratio establishes primary aldosteronism', 'A high ratio can result from drug-induced renin suppression. Aldosterone is not clearly elevated by the stated immunoassay threshold, while hypokalemia can lower the measured concentration. The present result therefore needs reassessment rather than a definitive PA label.'),
 ('Aldosterone below 10 ng/dL excludes PA despite the elevated ratio', 'Aldosterone below a usual cutoff would be reassuring only in an appropriately interpretable setting. Hypokalemia can lower aldosterone, so a single low value here cannot reliably exclude PA.'),
 ('Proceed directly to saline suppression using the current potassium and medications', 'Suppression testing can clarify selected intermediate-probability cases, especially when surgery is being pursued. Correcting the screening confounders first is more appropriate than carrying an uninterpretable baseline directly into a downstream test.')],
 [S('Biochemical Interpretation', '**Interpret aldosterone, renin and the ratio together.** Metoprolol can suppress renin and inflate the ratio; hypokalemia can suppress aldosterone and obscure genuine autonomous secretion.',
    'For commonly used immunoassays, the 2025 guidance gives a typical positive-screen framework of suppressed renin, aldosterone at least 10 ng/dL and an ARR above 20 when PRA is expressed in ng/mL/h. Local assay cutoffs and pretest probability still govern interpretation.',
    'LC-MS/MS uses a lower aldosterone boundary, typically 7.5 ng/dL, and different ratio calibration. A ratio calculated using direct renin concentration cannot be interpreted with a PRA-based numerical cutoff.'),
  S('Repeat Testing', '**Correct potassium and arrange a clinically safe repeat assessment.** A blanket instruction to stop all antihypertensives is inappropriate in a patient with significant pressure or cardiac risk.',
    'If safe and needed for clarification, beta blockers or central alpha-2 agonists may be withdrawn for about two weeks. MRAs, ENaC blockers and other diuretics generally require a longer, approximately four-week interval; ACE inhibitors and ARBs can also interfere and may require about two weeks.',
    'Minimal-withdrawal or no-withdrawal strategies are possible when necessary, provided the result is interpreted accordingly. Use an alternative regimen selected for the patient rather than creating uncontrolled hypertension to obtain a laboratory sample. In a convincing high-aldosterone phenotype, the presence of beta blockade does not automatically invalidate every positive result. Here the combination of a borderline-low aldosterone, hypokalemia and a renin-lowering drug makes reassessment the defensible choice. Imaging, suppression testing and eventual lateralization answer different questions and should not be inferred from the ratio alone.')], ['PA2025'],
 table=(['Measurement framework', 'Typical screening guidance; local assay validation required'], [['Low renin for typical screening framework', 'PRA ≤1 ng/mL/h or direct renin ≤8.2 mU/L'], ['Immunoassay aldosterone', '≥10 ng/dL with suppressed renin'], ['LC-MS/MS aldosterone', '≥7.5 ng/dL with suppressed renin'], ['Immunoassay aldosterone [ng/dL]/PRA [ng/mL/h]', '>20 with an appropriate aldosterone concentration'], ['Interpretation prerequisite', 'Review potassium, sodium intake, medications and assay units']]))

add(TOPIC, 'Overt Primary Aldosteronism and Suppression-Test Exceptions',
 'A patient with hypertension and documented spontaneous hypokalemia has repeated PRA 0.1 ng/mL/h and immunoassay aldosterone 32 ng/dL after potassium correction and appropriate medication review. They want surgical evaluation if eligible. Under Endocrine Society 2025 guidance, which next strategy is best?',
 'Proceed to the PA-specific localization pathway without routine aldosterone-suppression testing', [
 ('Require saline suppression before any PA-specific evaluation', 'Saline suppression can help selected intermediate-probability cases. In the overt renin-independent phenotype described, the guideline allows its omission and cautions about false-negative suppression results.'),
 ('Require oral sodium-loading confirmation before adrenal imaging or treatment', 'Oral sodium loading is another suppression approach for an appropriate selected patient. It is not a mandatory gateway when the supplied clinical and biochemical phenotype already meets the overt-disease exception.'),
 ('Require fludrocortisone suppression before discussing lateralization', 'Fludrocortisone suppression can be used in experienced centers with careful potassium and volume monitoring. Its complexity does not make it a required test in every positive PA assessment.')],
 [S('Biochemical Criteria', '**The 2025 pathway does not require a suppression test for every positive screen.** Hypertension with hypokalemia or resistance plus overt renin-independent aldosterone secretion can justify moving directly to PA-specific evaluation.',
    'The guidance describes PRA below 0.2 ng/mL/h or direct renin below 2 mU/L together with aldosterone above 20 ng/dL by immunoassay, or above 15 ng/dL by LC-MS/MS, in the relevant phenotype. This patient meets the immunoassay pattern after important confounders have been addressed.',
    'The rationale includes the possibility of a false-negative suppression result in an otherwise compelling case. This is a selected exception, not permission to diagnose PA from every mildly elevated ratio.'),
  S('Localization and Treatment Planning', '**Omitting suppression does not prove unilateral disease.** A patient seeking surgery still needs appropriate adrenal anatomy and usually AVS to establish functional lateralization.',
    'Adrenal CT evaluates structural lesions and possible malignancy. AVS distinguishes lateralizing secretion from bilateral disease when the patient is an appropriate surgical candidate; a visible nodule is not equivalent to an aldosterone-producing source.',
    'For an intermediate-probability result, suppression testing can still be useful after shared decision-making, particularly when it will determine pursuit of surgery. Choose the protocol according to comorbidity, safety and local expertise; sodium-loading procedures can be unsuitable in important volume-sensitive disease. If a patient declines or cannot undergo a surgical pathway, targeted MRA treatment can be appropriate without making every confirmatory procedure a prerequisite. Correct potassium and control pressure throughout the investigation. The critical distinctions are biochemical certainty, functional laterality and willingness or fitness for surgery; each changes the appropriate next step.')], ['PA2025'])

add(TOPIC, 'Adrenal CT and Functional Lateralization in PA',
 'A 56-year-old with established PA wants definitive surgery if appropriate. CT shows a 1.6-cm left adrenal adenoma and a normal-appearing right adrenal. What is the best test to guide the side of surgery?',
 'Adrenal venous sampling in an experienced center', [
 ('Repeat CT with washout calculations to identify the secreting side', 'Washout characteristics can help characterize an adrenal lesion structurally. They do not establish which gland is producing excess aldosterone or exclude bilateral secretion with an incidental left nodule.'),
 ('Repeat the peripheral ARR to determine whether the left gland is dominant', 'Peripheral aldosterone and renin assess the systemic biochemical phenotype. They do not provide side-specific secretion information, even when the ratio is strongly positive.'),
 ('Adrenal MRI to detect an occult right-sided adenoma', 'MRI can help characterize adrenal anatomy when CT is unsuitable or a lesion needs further assessment. Detecting or excluding another nodule still does not identify which gland is functionally responsible for aldosterone excess.')],
 [S('Anatomy Versus Function', '**CT and AVS answer complementary questions.** CT defines adrenal anatomy and identifies lesions requiring structural evaluation; AVS measures side-specific hormone secretion.',
    'A small aldosterone-producing lesion may not be visible, a visible lesion may be nonfunctioning, and both glands may contribute. Normal right-sided anatomy therefore does not prove absence of right-sided aldosterone production.',
    'AVS requires successful selective sampling and protocol-specific interpretation, generally accounting for dilution using cortisol or another validated approach. Technical success and local expertise matter before assigning a lateralization result.'),
  S('Surgical Eligibility and Associated Hormone Secretion', '**The Endocrine Society 2025 pathway generally combines CT and AVS before adrenalectomy.** A potential exception is a patient younger than 35 with marked PA, hypokalemia and a clearly unilateral adrenal adenoma larger than 1 cm; that exception does not fit this case.',
    'With an adrenal adenoma, assess possible autonomous cortisol secretion. A 1-mg overnight dexamethasone test is suggested; cortisol above 1.8 µg/dL after the test raises concern and requires appropriate endocrine interpretation.',
    'Cortisol cosecretion can complicate AVS interpretation and postoperative adrenal function. Confirm functional laterality and assess operative suitability before recommending unilateral adrenalectomy. If disease is bilateral, the patient declines surgery or a safe surgical pathway cannot be completed, an MRA-based plan remains appropriate. Surgical biochemical success does not guarantee that every patient becomes medication-free, because longstanding vascular changes and coexisting primary hypertension may persist. Continue postoperative pressure, potassium and renal surveillance rather than judging success from disappearance of an imaging lesion alone.')], ['PA2025'])

add(TOPIC, 'Medical Treatment of Bilateral Primary Aldosteronism',
 'A patient with bilateral PA takes spironolactone 25 mg daily. BP remains 150/92 mmHg and renin remains suppressed. Potassium is 3.8 mmol/L, eGFR 82 mL/min/1.73 m² and there are no limiting adverse effects. Which adjustment best follows the Endocrine Society 2025 treatment approach?',
 'Increase spironolactone to 50 mg daily', [
 ('Add amlodipine 5 mg daily', 'A CCB can be a useful additional BP drug. Here persistent hypertension with suppressed renin and well-tolerated low-dose MRA treatment supports optimizing aldosterone-directed therapy first.'),
 ('Replace spironolactone with amiloride 5 mg daily', 'An ENaC blocker can be an alternative when MRAs cannot be used or tolerated. It is less directly aligned with the recommended PA-specific strategy when an MRA is safe and has not yet been adequately titrated.'),
 ('Add doxazosin 1 mg at night', 'An alpha blocker can lower pressure, including during selected endocrine testing strategies. It does not address insufficient aldosterone blockade as directly as titrating a tolerated MRA in this phenotype.')],
 [S('Disease-Specific Treatment', '**Bilateral PA is generally managed medically with mineralocorticoid receptor blockade.** In lateralizing disease, a suitable patient who wants surgery may instead receive unilateral adrenalectomy after appropriate evaluation.',
    'A common low spironolactone starting dose is 12.5–25 mg daily. The current 25-mg dose can be increased, for example to 50 mg daily, when laboratory findings, pressure and tolerance permit; some PA patients need further specialist-guided titration.',
    'The 2025 recommendation specifically supports increasing aldosterone-directed treatment when BP remains uncontrolled and renin is still suppressed. It does not specify one universal numerical renin target.'),
  S('Monitoring and Limitations', '**Follow potassium, kidney function and symptoms during titration.** Potassium supplements and other antihypertensives may need adjustment as aldosterone action is blocked and pressure falls.',
    'Check early laboratory responses according to renal and potassium risk. A modest fall in filtration can reflect correction of aldosterone-associated hyperfiltration, but a large deterioration, symptomatic hypotension or hyperkalemia requires reassessment.',
    'Spironolactone can cause breast tenderness, gynecomastia or menstrual effects; a more selective MRA may be appropriate if these become limiting. Reducing sodium intake supports the treatment response. When pressure is already controlled, the clinical benefit of escalating solely to raise renin remains uncertain, so that different scenario should not be confused with this uncontrolled patient. An unchanged suppressed renin value also requires interpretation with concomitant medicines and the overall response. The objective is adequate disease-specific treatment with safe pressure and electrolyte control, not pursuit of an isolated biomarker regardless of adverse effects.')], ['PA2025', 'AHA2025'])

add(TOPIC, 'Renal-Artery Stenosis: Selecting Revascularization Review',
 'Which renal-artery stenosis phenotype most strongly supports specialist consideration of revascularization?',
 'Severe bilateral renal-artery disease with recurrent flash pulmonary edema despite medical care', [
 ('Unilateral 70% atherosclerotic stenosis with stable renal function and controlled BP', 'Anatomic narrowing alone does not establish benefit from intervention. Stable kidney function and effective medical control favor continued vascular-risk and BP management with surveillance.'),
 ('Bilateral moderate stenoses with stable renal function and no circulatory episodes', 'Moderate anatomical lesions do not necessarily produce important renal ischemia. Without an attributable high-risk syndrome, routine stenting is not supported simply because both arteries appear abnormal.'),
 ('An incidental severe lesion supplying a small atrophic kidney with controlled BP', 'A severe image finding can draw attention, but an atrophic kidney may have limited recoverable function. Assess viability and the overall syndrome rather than assuming that opening every severe lesion improves outcomes.')],
 [S('Trial Interpretation', '**CORAL did not establish a routine clinical-event benefit from adding renal-artery stenting to comprehensive medical care in the studied atherosclerotic population.** This argues against treating a percentage stenosis alone.',
    'Medical care includes pressure control, atherosclerotic risk reduction and monitoring of kidney function. Renin–angiotensin blockade can be useful but requires careful renal and potassium surveillance, especially when bilateral hemodynamically important disease is suspected.',
    'A trial’s average result should not be converted into a prohibition on investigating every high-risk presentation. Some unstable syndromes were poorly represented in routine-intervention trials.'),
  S('High-Risk Clinical Syndromes', '**Recurrent flash pulmonary edema associated with severe renovascular disease is a recognized reason for selective multidisciplinary review.** Other concerning patterns can include rapidly worsening kidney function or difficult pressure control when a hemodynamically important lesion plausibly contributes.',
    'Assess whether the kidney is viable and the syndrome is attributable to renovascular disease. Before intervention, consensus criteria for lesion significance include more than 70% luminal narrowing, a mean translesional gradient above 10 mmHg or renal fractional flow reserve below 0.8; these findings still require a compatible clinical indication.',
    'Benefits reported in selected pulmonary-edema cohorts are largely observational, so do not present intervention as a guaranteed mortality or kidney-failure benefit. Continue medical stabilization and risk-factor treatment while specialist assessment proceeds. The choice of angioplasty, stenting or another approach depends on the lesion; atherosclerotic ostial disease and renal FMD do not share an identical procedural strategy. Follow BP, renal function and recurrence after any intervention because revascularization does not erase coexisting vascular disease or primary hypertension.')], ['CORAL', 'RENOVASCULAR'],style='direct')

add(TOPIC, 'Renal Fibromuscular Dysplasia: Angioplasty Strategy',
 'A 31-year-old woman has confirmed difficult-to-control hypertension and hemodynamically important multifocal renal FMD. A specialist team has selected revascularization. Which initial procedural strategy is generally preferred?',
 'Balloon angioplasty without routine stent placement', [
 ('Primary bare-metal stenting of the affected renal segment', 'Stenting is commonly used for selected atherosclerotic renal lesions and may be needed as a bailout for a procedural complication. Routine primary stenting is not the preferred FMD strategy.'),
 ('Primary covered-stent placement across the affected segment', 'A covered stent can be useful for selected aneurysms, rupture or other vascular complications. It is not the default treatment of an uncomplicated stenotic FMD segment.'),
 ('Open aortorenal bypass as the first procedure', 'Surgery retains a role for complex anatomy, associated aneurysm or failed endovascular treatment. When a suitable FMD lesion can be treated percutaneously, balloon angioplasty is generally the initial approach.')],
 [S('Disease Pattern and Evaluation', '**Renal FMD is a nonatherosclerotic arterial disorder that can cause renovascular hypertension, often in younger adults.** Multifocal disease commonly produces alternating narrowing and dilatation in mid-to-distal arterial segments.',
    'That distribution differs from the usual ostial or proximal atherosclerotic lesion. Clinical age and a beaded appearance support the diagnosis, but the decision to intervene also requires assessment of lesion significance and the pressure phenotype.',
    'A visible lesion need not be the only contributor to hypertension. Confirm adherence and out-of-office pressure, review renal function and consider the likelihood of a meaningful treatment response before selecting revascularization.'),
  S('Treatment and Follow-Up', '**When intervention is indicated, balloon angioplasty without routine stenting is the usual FMD strategy.** Stent placement is reserved for specific circumstances such as a flow-limiting dissection or another complication rather than used automatically.',
    'Young age, a shorter hypertension history and a favorable lesion can improve the prospect of response, but cure is not assured. Some patients still need antihypertensive treatment after technically successful angioplasty.',
    'Monitor renal function, access-site complications, BP and possible restenosis. FMD can involve more than one vascular territory; assess associated aneurysm or dissection risk using an appropriate vascular evaluation rather than treating the kidney image as an isolated finding. Medical BP treatment remains appropriate when the lesion is not a good procedural target or expected benefit is low. Atherosclerotic-stenting trial results cannot be transferred uncritically to this distinct disease. Conversely, a successful FMD procedure is not evidence that an older patient with an incidental atherosclerotic lesion should undergo routine intervention.')], ['RENOVASCULAR', 'ESC2024'])

add(TOPIC, 'Suspected OSA After a Negative Home Sleep Test',
 'An obese adult with resistant hypertension, loud snoring, witnessed apneas and daytime sleepiness has a technically adequate but negative home sleep-apnea test. Clinical suspicion remains high. Which investigation is most appropriate next?',
 'Attended overnight polysomnography', [
 ('Repeat home sleep-apnea testing', 'Home testing is useful in selected uncomplicated adults at increased risk. AASM guidance recommends polysomnography after a single negative, inconclusive or technically inadequate home test when OSA remains suspected, rather than using repeated home testing as the default response.'),
 ('Overnight pulse oximetry alone', 'Oximetry can reveal desaturation and assist selected assessments, but it lacks the full respiratory and sleep information needed to resolve a negative home study with persistent clinical suspicion. A normal oximetry result also does not exclude OSA.'),
 ('Multiple sleep latency testing', 'This test evaluates selected central hypersomnolence disorders after appropriate overnight assessment. It does not replace the respiratory sleep study required to investigate suspected obstructive events in this setting.')],
 [S('Diagnostic Testing', '**A negative home test does not reliably exclude OSA when the clinical probability remains high.** Home systems may underestimate event frequency because recording time can exceed actual sleep time and because their signals and scoring differ from laboratory polysomnography.',
    'Polysomnography records sleep and respiratory physiology more comprehensively. It is also preferred from the outset in important cardiorespiratory disease, suspected hypoventilation, certain neuromuscular disorders, chronic opioid use, previous stroke or severe insomnia.',
    'A screening questionnaire or a characteristic symptom cluster estimates risk but does not independently establish the diagnosis. Confirming OSA also allows treatment planning based on severity, symptoms and comorbidity.'),
  S('Hypertension and Treatment', '**Intermittent hypoxemia, arousals and sympathetic activation can contribute to resistant and nocturnal hypertension.** Assess the sleep phenotype without assuming that it is the only cause of poor BP control.',
    'CPAP can improve OSA-related symptoms and can produce a generally modest, adherence-dependent BP improvement. It should complement weight management, pressure medication and review of other contributors rather than be presented as a guaranteed replacement for antihypertensives.',
    'Follow device use, residual events, symptoms and home or ambulatory pressure after treatment. Persistent daytime sleepiness despite adequate OSA treatment may warrant evaluation for other causes. Avoid converting a favorable sleep or BP response into an unsupported claim that every treated patient has a proven reduction in cardiovascular events. The immediate decision here is diagnostic: use the more definitive overnight assessment rather than dismissing a high-probability clinical presentation because one limited home study was negative.')], ['OSA_DIAG', 'HIPARCO', 'AHA2025'])

add(TOPIC, 'Pheochromocytoma: Alpha and Beta Blockade Sequencing',
 'A patient with a functional adrenal pheochromocytoma is being prepared for elective surgery. BP is 172/100 mmHg and sinus rate 116/min. Which preparation strategy is most appropriate?',
 'Establish adequate alpha blockade, then add a beta blocker if tachycardia persists', [
 ('Start a beta blocker first, adding an alpha blocker after the rate is controlled', 'Rate control can be appropriate after alpha blockade. Starting it first can remove beta-mediated vasodilatation while alpha-mediated vasoconstriction remains active, provoking a dangerous pressure rise.'),
 ('Use labetalol alone as the initial complete adrenergic-blocking regimen', 'Labetalol has both actions, but its beta-blocking effect predominates and it is not a reliable substitute for adequate initial alpha blockade in this preparation pathway.'),
 ('Start phenoxybenzamine and propranolol together with the first doses', 'The two agents may both be used during preparation, but alpha blockade needs to be established before beta blockade is added. Starting both simultaneously does not demonstrate that protective sequence.')],
 [S('Pathophysiology and Treatment Sequence', '**Catecholamine-related vasoconstriction must be addressed before introducing beta blockade for tachycardia.** The sequence protects against an abrupt increase in alpha-mediated vascular resistance.',
    'Functional PPGL generally requires a specialist preoperative preparation plan. Alpha blockade is usually titrated over about 7–14 days, with the exact period guided by pressure, postural tolerance, heart rate and comorbidity.',
    'Phenoxybenzamine or a selective alpha-1 blocker such as doxazosin can be used. A common doxazosin starting dose is 1–2 mg daily, with cautious escalation according to the monitored response; regimens are individualized rather than based on a single fixed dose for all patients.'),
  S('Volume Status and Monitoring', '**Assess seated and standing pressure, symptoms and volume status throughout preparation.** Catecholamine excess can contract the effective circulating volume, and appropriate salt and fluid replacement after blockade can reduce perioperative instability.',
    'Volume expansion requires particular care in heart failure or kidney disease. Add a suitable beta blocker only after adequate alpha blockade if tachycardia remains a treatment problem; do not chase the rate while ignoring vascular resistance.',
    'Anesthesia, surgery and endocrine teams should coordinate medication and intraoperative planning. Severe acute catecholamine crises require a monitored emergency approach rather than merely following an outpatient titration schedule. Calcium-channel blockers or metyrosine can be useful in selected situations, but do not make mixed alpha/beta blockade interchangeable with the usual preparation sequence. After surgery, monitor hypotension and glucose as well as the possibility of persistent disease. The presence of tachycardia therefore changes the eventual combination, while the alpha-first requirement determines its order.')], ['PPGL', 'PPGL2025'])

add(TOPIC, 'Liddle Syndrome: ENaC-Directed Treatment',
 'A 19-year-old with familial early-onset hypertension has hypokalemic metabolic alkalosis, suppressed renin and low aldosterone. Testing identifies a pathogenic gain-of-function SCNN1B variant. Which drug most directly addresses the mechanism?',
 'Amiloride', [
 ('Spironolactone', 'Spironolactone targets mineralocorticoid receptor activation and is useful in PA and other selected aldosterone-mediated states. The channel abnormality here drives sodium reabsorption despite suppressed aldosterone, so receptor antagonism is not the most direct treatment.'),
 ('Eplerenone', 'Eplerenone is a more selective MRA and can replace spironolactone for selected adverse effects. Its greater receptor specificity does not correct constitutive ENaC overactivity downstream of the mineralocorticoid receptor.'),
 ('Dexamethasone', 'Glucocorticoid suppression can be relevant to ACTH-dependent familial hyperaldosteronism after appropriate diagnosis. That is an aldosterone-producing disorder, whereas this patient has a demonstrated sodium-channel mechanism with low aldosterone.')],
 [S('Genetics and Pathophysiology', '**Liddle syndrome is an inherited gain-of-function disorder of the epithelial sodium channel.** Increased distal sodium reabsorption expands volume and promotes potassium and hydrogen loss, suppressing renin and aldosterone.',
    'SCNN1B and SCNN1G are characteristic genes. The phenotype can be variably expressed, so lack of hypokalemia in another affected relative does not exclude a pathogenic familial variant.',
    'Low renin alone does not distinguish the syndrome from PA; the low aldosterone and the molecular result identify a different mechanism. Apparent mineralocorticoid excess and liquorice exposure can also produce low-renin, low-aldosterone hypertension and require a different etiological assessment.'),
  S('Treatment and Monitoring', '**Amiloride directly blocks ENaC and is combined with dietary sodium reduction.** A common starting dose is 5 mg daily, titrated according to BP, potassium, renal function and the individual response.',
    'Triamterene is another ENaC-blocking option. Monitor potassium and kidney function as treatment corrects potassium wasting; a potassium-sparing drug can still cause hyperkalemia when kidney function changes or interacting medicines are added.',
    'Review potassium supplements and avoid assuming that lifelong hypokalemia makes monitoring unnecessary. Offer appropriate genetic counseling and assessment of at-risk relatives when a pathogenic familial variant is established. Longstanding hypertension can cause cardiac, cerebral and kidney complications even when the patient is young, so durable treatment and follow-up matter. A response to amiloride can support the physiological reasoning, but it should not replace evaluation of other low-renin disorders when the genetic diagnosis is uncertain. The treatment distinction is between blocking an overactive channel and blocking an upstream hormone receptor that is not driving this case.')], ['LIDDLE', 'AHA2025', 'AMILORIDE'],
 table=(['Condition', 'Renin / aldosterone pattern', 'Treatment principle'], [['Primary aldosteronism', 'Low renin; aldosterone inappropriate or high', 'MRA or selected unilateral surgery'], ['Liddle syndrome', 'Both suppressed', 'ENaC blockade and sodium reduction'], ['Apparent mineralocorticoid excess or liquorice effect', 'Often both suppressed', 'Identify cause; reduce mineralocorticoid action'], ['Gordon syndrome', 'Low-renin hypertension with hyperkalemia/acidosis', 'Thiazide-sensitive sodium transport phenotype']]))

add(TOPIC, 'Coarctation as a Cause of Young-Onset Hypertension',
 'A 28-year-old has BP 170/94 mmHg in both arms and systolic pressure 112 mmHg in the legs. Femoral upstrokes are delayed relative to the radial pulses, and there is a systolic murmur over the left interscapular region. Which diagnosis best localizes the cause?',
 'Coarctation of the proximal descending thoracic aorta', [
 ('Renal-artery fibromuscular dysplasia', 'Renal FMD is an important cause of young-onset hypertension and may produce an abdominal bruit. It does not by itself produce a fixed arm–leg pressure difference and radiofemoral delay from an aortic obstruction.'),
 ('Takayasu arteritis involving the aortic arch branches', 'Large-vessel vasculitis can cause hypertension and pulse abnormalities. Arch-branch involvement more often produces arm asymmetry or upper-limb pulse deficits; the symmetrical arm pressure and lower-body delay with a posterior thoracic murmur favor coarctation in this stem.'),
 ('Aortoiliac atherosclerotic occlusive disease', 'Distal aortic disease can reduce leg pressure and pulses, but usually occurs in a different vascular-risk and symptom context. It does not explain the characteristic posterior thoracic murmur as well as a congenital thoracic narrowing.')],
 [S('Clinical Localization', '**Upper-body hypertension with delayed lower-limb arterial upstrokes suggests an obstruction between the arm and leg circulations.** A posterior thoracic murmur supports coarctation rather than an isolated endocrine or renal-artery cause.',
    'Measure pressure in both arms and a lower extremity using appropriate technique. An arm–leg systolic difference above 20 mmHg is an important signal, but a modest measured gradient does not exclude severe disease when collateral flow or reduced ventricular output affects the result.',
    'Assess associated bicuspid aortic valve, ventricular hypertrophy and other congenital findings. Absence of a childhood diagnosis does not exclude presentation in adulthood.'),
  S('Imaging, Treatment and Follow-Up', '**CMR or CT angiography defines the thoracic aorta, narrowing, arch anatomy and collaterals.** Echocardiography assesses associated valve disease, ventricular function and Doppler findings.',
    'Do not equate a Doppler peak instantaneous gradient with an invasive peak-to-peak gradient. Contemporary aortic guidance uses the clinical pressure phenotype, anatomy and appropriate hemodynamic evidence together when deciding intervention.',
    'Significant native or recurrent coarctation with hypertension merits congenital/aortic specialist assessment for stenting or surgery according to anatomy and suitability. Treat pressure medically while planning care, and continue surveillance after repair because residual hypertension, recurrent narrowing and aneurysm can occur. The 2025 ACHD guidance reinforces arm-and-leg BP assessment and individualized long-term imaging. Screening for associated intracranial aneurysms may be considered in selected adult guidance rather than treated as an automatic identical rule across all societies. Repair of the narrowing is not a reason to abandon lifelong cardiovascular follow-up or ignore pressure outside the clinic.')], ['ACHD2025', 'AORTIC2022', 'ESC2024'])
